args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?dirIRI ?dirLabel ?deathDate WHERE {
  VALUES ?film { dbr:You're_on_Your_Own dbr:Terror_at_Tenkiller }

  OPTIONAL { ?film dbo:director ?dirIRI . }
  OPTIONAL {
    ?film dbp:director ?dirLit .
    BIND(STR(?dirLit) AS ?dirName)
    # attempt to resolve literal director name to an entity via rdfs:label
    OPTIONAL {
      ?candidate rdfs:label ?candLabel .
      FILTER(LCASE(STR(?candLabel)) = LCASE(?dirName) )
      BIND(?candidate AS ?dirFromLabel)
    }
  }

  # use either the dbo:director or the resolved label candidate
  BIND(COALESCE(?dirIRI, ?dirFromLabel) AS ?resolvedDir)
  BIND(?resolvedDir AS ?dirIRI)

  OPTIONAL { ?dirIRI dbo:deathDate ?deathDate . }
  OPTIONAL { ?dirIRI rdfs:label ?dirLabel . FILTER(langMatches(lang(?dirLabel), "en")) }

  ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "en"))
}
ORDER BY DESC(?deathDate)

